#include <stdio.h>

int main(void) {
    int L, C;
    if (scanf("%d %d", &L, &C) != 2) return 0;

    char grid[100][100];
    int sr = -1, sc = -1;

    for (int i = 0; i < L; i++) {
        scanf("%s", grid[i]);
        for (int j = 0; j < C; j++) {
            if (grid[i][j] == 'o') {
                sr = i;
                sc = j;
            }
        }
    }

    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    int prev_r = sr, prev_c = sc;
    int curr_r = -1, curr_c = -1;

    // Find the unique H neighbor of 'o'
    for (int d = 0; d < 4; d++) {
        int nr = sr + dr[d];
        int nc = sc + dc[d];
        if (nr >= 0 && nr < L && nc >= 0 && nc < C && grid[nr][nc] == 'H') {
            curr_r = nr;
            curr_c = nc;
            break;
        }
    }

    // Follow the path until the current position is reached
    while (1) {
        int next_r = -1, next_c = -1;

        for (int d = 0; d < 4; d++) {
            int nr = curr_r + dr[d];
            int nc = curr_c + dc[d];
            if (nr >= 0 && nr < L && nc >= 0 && nc < C &&
                grid[nr][nc] == 'H' &&
                !(nr == prev_r && nc == prev_c)) {
                next_r = nr;
                next_c = nc;
                break;
            }
        }

        if (next_r == -1) {
            break;
        }

        prev_r = curr_r;
        prev_c = curr_c;
        curr_r = next_r;
        curr_c = next_c;
    }

    printf("%d %d\n", curr_r + 1, curr_c + 1);
    return 0;
}
